import {VehiclePowertrain} from './vehicle-powertrain.js';
import {componentDefaultValues,objectComponents,enabledComponent,validComponentProperties} from './scene-components.js';
import {validVehicleInput} from './vehicle-config.js';
const vec=v=>({x:v[0],y:v[1],z:v[2]});
export class RaycastVehicles{
 constructor(space,objects,{queryOnly=false,frame}={}){this.space=space;this.objects=objects;this.queryOnly=queryOnly;this.frame=frame;this.items=new Map();}
 remove(id){const item=this.items.get(id);if(!item)return;this.space.world.removeVehicleController(item.controller);delete item.object.gameplayDebug?.vehicle;this.frame?.(item.object,null);this.items.delete(id);}
 sync(){if(this.queryOnly)return;const active=new Set();for(const object of this.objects){if(object.poolActive===false)continue;const components=objectComponents(object).filter(c=>c.type==='RaycastVehicle'&&c.properties?.enabled!==false);if(components.length>1)throw Error('차체에는 차량 컴포넌트를 하나만 추가하세요.');const component=components[0];if(!component)continue;const p={...componentDefaultValues('RaycastVehicle'),...component.properties};if(!validComponentProperties('RaycastVehicle',p))throw Error('차량 휠·조종 설정을 확인하세요.');const body=this.space.bodies.get(object.id);if(!body?.p||!body.body.isDynamic()||enabledComponent(object,'Rigidbody2D'))throw Error('차량에는 동적 3D Rigidbody가 필요해요.');active.add(object.id);const signature=JSON.stringify([body.nonce,p.wheels]);let item=this.items.get(object.id);if(item?.signature!==signature){const controller=this.space.world.createVehicleController(body.body);try{controller.indexUpAxis=1;controller.setIndexForwardAxis=2;for(const [i,w] of p.wheels.entries()){controller.addWheel(vec(w.position),vec([0,-1,0]),vec([-1,0,0]),w.restLength,w.radius);for(const [suffix,key]of [['SuspensionStiffness','stiffness'],['SuspensionCompression','compression'],['SuspensionRelaxation','relaxation'],['MaxSuspensionForce','maxForce'],['MaxSuspensionTravel','travel'],['FrictionSlip','friction'],['SideFrictionStiffness','sideFriction']])controller['setWheel'+suffix](i,w[key]);}}catch(error){this.space.world.removeVehicleController(controller);throw error;}this.remove(object.id);item={object,body,component,controller,signature};this.items.set(object.id,item);}const configuration=JSON.stringify(p);if(item.configuration!==configuration)body.body.wakeUp();item.configuration=configuration;item.p=p;item.object=object;item.component=component;if(p.driveModel==='powertrain'){item.powertrain??=new VehiclePowertrain(p);}else item.powertrain=null;}for(const id of this.items.keys())if(!active.has(id))this.remove(id);}
 input(object,throttle,steering,brake=0,handbrake=0){if(!validVehicleInput(throttle,steering,brake,handbrake))throw Error('차량 입력 범위를 확인하세요.');const item=this.items.get(object.id);if(!item)throw Error('활성 차량이 필요해요.');Object.assign(item.component.properties,{throttle,steering,brake,handbrake});Object.assign(item.p,{throttle,steering,brake,handbrake});item.body.body.wakeUp();}
 gear(object,gear){const item=this.items.get(object.id);if(!item?.powertrain)throw Error('엔진·변속기 차량이 필요해요.');item.powertrain.setGear(gear,item.p);item.component.properties.gear=gear;item.p.gear=gear;item.body.body.wakeUp();}
 step(dt){for(const item of this.items.values()){const {controller:c,p,body}=item;if(body.body.isSleeping()&&!p.throttle&&!p.steering&&!p.brake&&!p.handbrake&&!item.powertrain?.remaining)continue;item.powertrain?.step(p,c,body.body,dt);for(const [i,w]of p.wheels.entries()){c.setWheelEngineForce(i,item.powertrain?item.powertrain.forces[i]:w.drive?p.throttle*p.engineForce:0);c.setWheelSteering(i,w.steer*p.steering*p.maxSteerAngle*Math.PI/180);c.setWheelBrake(i,Math.max(w.brake?Math.max(p.brake,item.powertrain?.braking||0)*(item.powertrain?p.brakeTorque/w.radius*dt:p.brakeImpulse):0,w.handbrake?p.handbrake*(item.powertrain?p.handbrakeTorque/w.radius*dt:p.handbrakeImpulse):0));}if(p.throttle||p.steering||p.brake||p.handbrake)body.body.wakeUp();
 // The WASM query borrows the collider set: predicates use mirrored data only.
 c.updateVehicle(dt,this.space.R.QueryFilterFlags.EXCLUDE_SENSORS,undefined,collider=>{const hit=this.space.colliders.get(collider.handle);return !!hit&&hit.object.id!==item.object.id&&!hit.p.trigger&&hit.p.collisionMode!=='query'&&((p.groundMask>>>0)&(1<<hit.p.layer))!==0;});}}
 publish(){for(const {object,controller:c,p,body,powertrain}of this.items.values()){const q=body.body.rotation(),v=body.body.linvel(),forward=[2*(q.x*q.z+q.w*q.y),2*(q.y*q.z-q.w*q.x),1-2*(q.x*q.x+q.y*q.y)],speed=v.x*forward[0]+v.y*forward[1]+v.z*forward[2];const state={speed,...(powertrain?powertrain.inspect():{gear:0,targetGear:0,shifting:false,shiftRemaining:0,engineRPM:0,engineTorque:0}),driveModel:p.driveModel,wheelCount:c.numWheels(),wheels:p.wheels.map((w,i)=>({position:w.position,radius:w.radius,width:w.width,suspension:c.wheelSuspensionLength(i)??w.restLength,rotation:c.wheelRotation(i)||0,steering:c.wheelSteering(i)||0,contact:c.wheelIsInContact(i),force:c.wheelSuspensionForce(i)||0,driveForce:c.wheelEngineForce(i)||0,rpm:powertrain?.wheelRPM[i]||0}))};object.gameplayDebug={...object.gameplayDebug,vehicle:state};this.frame?.(object,state);}}
 dispose(){for(const id of [...this.items.keys()])this.remove(id);}
}
